{
  "name": "@playerplanet/opencode-career-ops",
  "version": "1.0.0",
  "description": "Career-Ops job search automation for OpenCode - AI-powered offer evaluation, CV generation, and application tracking",
  "main": "index.js",
  "bin": {
    "career-ops-setup": "./bin/setup.js",
    "career-ops-init": "./bin/init.js"
  },
  "scripts": {
    "setup": "node bin/setup.js",
    "init": "node bin/init.js",
    "test": "echo \"Tests not yet implemented\" && exit 0",
    "lint": "echo \"Linting not yet implemented\" && exit 0"
  },
  "keywords": [
    "opencode",
    "opencode-skill",
    "career",
    "job-search",
    "resume",
    "cv",
    "pdf-generation",
    "application-tracking",
    "ai-agent"
  ],
  "author": "Konsta Kiirikki <konsta.kiirikki@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/PlayerPlanet/opencode-career-ops.git"
  },
  "bugs": {
    "url": "https://github.com/PlayerPlanet/opencode-career-ops/issues"
  },
  "homepage": "https://github.com/PlayerPlanet/opencode-career-ops#readme",
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "playwright": "^1.40.0",
    "yaml": "^2.3.0",
    "commander": "^11.0.0",
    "chalk": "^4.1.2",
    "inquirer": "^8.2.6"
  },
  "peerDependencies": {
    "opencode": ">=1.0.0"
  },
  "files": [
    "src/",
    "bin/",
    "templates/",
    "README.md",
    "LICENSE"
  ],
  "opencode": {
    "skillsDir": "src/skills",
    "requires": [
      "playwright"
    ]
  }
}
